"""zip-password-finder - Find the password of protected ZIP files"""

import argparse
import sys
import os
import zipfile
import time
import itertools
import string
from concurrent.futures import ThreadPoolExecutor, as_completed

VERSION = "0.10.3"

# Character sets
CHARSETS = {
    'l': string.ascii_lowercase,
    'u': string.ascii_uppercase,
    'd': string.digits,
    'h': '0123456789abcdef',
    'H': '0123456789ABCDEF',
    's': ' \t\n\r!@#$%^&*()_+-=[]{}|;:,.<>?'
}

def load_charset_from_file(filepath):
    """Load charset from a file, one character per line"""
    charset = set()
    try:
        with open(filepath, 'r') as f:
            for line in f:
                char = line.strip()
                if char:
                    charset.add(char)
    except Exception as e:
        print(f"CLI argument error - '{filepath}' cannot be read", file=sys.stderr)
        sys.exit(1)
    return charset

def test_password(zip_path, password, file_number):
    """Test if a password works for the given ZIP file"""
    try:
        if file_number >= 0:
            with zipfile.ZipFile(zip_path, 'r') as zf:
                if file_number < len(zf.namelist()):
                    zf.extract(zf.namelist()[file_number], path='/tmp/extracted', pwd=password.encode())
                else:
                    return False
        else:
            with zipfile.ZipFile(zip_path, 'r') as zf:
                # Try to extract all files
                for name in zf.namelist():
                    zf.extract(name, path='/tmp/extracted', pwd=password.encode())
        return True
    except Exception:
        return False

def generate_passwords(charset, min_len, max_len, starting_password=None):
    """Generate passwords based on charset and length range"""
    chars = sorted(charset)  # Sort characters to match original behavior
    if starting_password:
        yield starting_password
        # Generate passwords starting from the given one
        current = list(starting_password)
        while True:
            found = False
            for i in range(len(current) - 1, -1, -1):
                idx = chars.index(current[i])
                if idx < len(chars) - 1:
                    current[i] = chars[idx + 1]
                    found = True
                    break
                else:
                    current[i] = chars[0]
            if not found:
                break
            yield ''.join(current)
    else:
        for length in range(min_len, max_len + 1):
            for combo in itertools.product(chars, repeat=length):
                yield ''.join(combo)

def format_time(elapsed):
    """Format elapsed time to match original executable's output format"""
    us = int(elapsed * 1000000)
    ns = int((elapsed * 1000000000) % 1000)
    ms = us // 1000
    us = us % 1000
    if ms > 0:
        return f"Time elapsed: {ms}ms {us}us {ns}ns"
    else:
        return f"Time elapsed: {us}us {ns}ns"

def main():
    # Check for --version before parsing
    if '--version' in sys.argv or '-V' in sys.argv:
        print(f"zip-password-finder {VERSION}")
        sys.exit(0)

    parser = argparse.ArgumentParser(
        description='Find the password of protected ZIP files',
        formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument('-i', '--inputFile', required=True, help='path to zip input file')
    parser.add_argument('-w', '--workers', type=int, default=1, help='number of workers')
    parser.add_argument('-p', '--passwordDictionary', help='path to a password dictionary file')
    parser.add_argument('-c', '--charset', default='lud', help='charset to use to generate password')
    parser.add_argument('--charsetFile', help='path to a charset file')
    parser.add_argument('--minPasswordLen', type=int, default=1, help='minimum password length')
    parser.add_argument('--maxPasswordLen', type=int, default=10, help='maximum password length')
    parser.add_argument('--fileNumber', type=int, default=0, help='file number in the zip archive')
    parser.add_argument('-s', '--startingPassword', help='password to start from')
    parser.add_argument('-V', '--version', action='store_true', help='Print version')

